insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$vila-velha$q$, $q$https://legislacao.vilavelha.es.gov.br/Arquivo/Documents/legislacao/html/D1612001.html (Dec. 161/2001; situação 'Em Vigor' em https://legislacao.vilavelha.es.gov.br/consulta-legislacao.aspx?tipo=6&numero=161&ano=2001&interno=0)$q$, $q$Ato oficial da Prefeitura de Vila Velha: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap) — bairros (admin_level 10), vias e áreas portuárias do OSM, cortados à mão (data/raw/municipios/curadoria/grande_vitoria.py).$q$, 45, $q$Dec. 161/2001 (assinado em 22/06/2001, Boletim Oficial de 15/08/2001, vigência 60 dias depois), sem alterações. O critério é o PBT; o município não define VUC. A Terceira Ponte (estadual, Sistema Rodovia do Sol) fica fora das zonas municipais e tem regra própria no arquivo de Vitória (es_terceira_ponte_lei_9602).$q$);
